import sys
from collections import defaultdict

class TrieNode:
    def __init__(self):
        self.children = defaultdict(TrieNode)
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word):
        node = self.root
        for char in word:
            if char in node.children:
                node = node.children[char]
            else:
                return False
        return node.is_end_of_word

    def delete_and_search(self, word):
        def dfs(node, word, index):
            if index == len(word):
                return node.is_end_of_word
            char = word[index]
            if char in node.children:
                if dfs(node.children[char], word, index + 1):
                    return True
                # Try skipping the current character
                if dfs(node, word, index + 1):
                    return True
            return False

        return dfs(self.root, word, 0)

def find_typos(words):
    trie = Trie()
    for word in words:
        trie.insert(word)

    typos = []
    for word in words:
        if trie.delete_and_search(word):
            typos.append(word)

    return typos

